{
  "query": "query Build($id: ID!) { build(id: $id) { id number status ... on CompletedBuild { result branch commit componentCount specCount storybookUrl webUrl } } }",
  "variables": { "id": "BUILD_ID" }
}

{
  "query": "query LastBuild($id: ID!) { project(id: $id) { lastBuild(defaultBranch: true, statuses: [PASSED, PENDING, ACCEPTED]) { id number status } } }",
  "variables": { "id": "PROJECT_ID" }
}

{
  "query": "query Tests($id: ID!) { build(id: $id) { ... on CompletedBuild { testCount(statuses: [PENDING]) tests(first: 20) { edges { node { id status result story { name } comparisons { result browser { key } } } } } } } }",
  "variables": { "id": "BUILD_ID" }
}

{
  "query": "mutation ReviewTest($input: ReviewTestInput!) { reviewTest(input: $input) { updatedTests { id status } userErrors { message } } }",
  "variables": { "input": { "testId": "TEST_ID", "status": "ACCEPTED", "batch": "SPEC" } }
}

{
  "query": "query Project($id: ID!) { project(id: $id) { id name features { uiReview uiTests } branchNames webUrl } }",
  "variables": { "id": "PROJECT_ID" }
}
